/**
 * A three-way merge for the generated contract manifest
 * (`packages/protocol/contracts/manifest.json`).
 *
 * Any two branches that add a command both change `counts.commands`, so the
 * manifest conflicted on every merge and was regenerated by hand. Its maps
 * (`commands`, `events`, `domains`) are keyed records the generator sorts, and
 * `counts` and `untypedByDomain` are totals derived from `commands`. So the
 * maps merge entry by entry, the totals are recomputed, and the result is
 * written in the generator's own format. An entry both sides changed
 * differently, or a shape this does not know, returns null and the caller
 * falls back to Git's text merge.
 *
 * The merged manifest describes the merged entries, which is what the merged
 * registry generates unless the two sides' source changes interact. Running
 * `mise run contract:check` after the merge, as the repository's instructions
 * say, catches that case.
 */
import {
  CONTRACT_MANIFEST_SCHEMA_VERSION,
  serializeContractManifest,
} from "../contract-manifest-format.ts";

type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type Record_ = { [key: string]: Json };

const MAPS = ["commands", "events", "domains"] as const;
const DERIVED = ["counts", "untypedByDomain"] as const;
const SCALARS = ["schemaVersion", "generatedBy"] as const;
const KNOWN = new Set<string>([...MAPS, ...DERIVED, ...SCALARS]);

function parse(text: string): Record_ | null {
  try {
    const value = JSON.parse(text) as Json;
    if (!value || typeof value !== "object" || Array.isArray(value)) return null;
    if (Object.keys(value).some((key) => !KNOWN.has(key))) return null;
    for (const key of MAPS) {
      const map = value[key];
      if (!map || typeof map !== "object" || Array.isArray(map)) return null;
    }
    return value;
  } catch {
    return null;
  }
}

const same = (left: Json | undefined, right: Json | undefined) =>
  JSON.stringify(left) === JSON.stringify(right);

/** The three-way value, `undefined` for removed, or `conflict`. */
function pick(
  base: Json | undefined,
  ours: Json | undefined,
  theirs: Json | undefined,
): Json | undefined | "conflict" {
  if (same(ours, theirs)) return ours;
  if (same(ours, base)) return theirs;
  if (same(theirs, base)) return ours;
  return "conflict";
}

function sorted(record: Record_): Record_ {
  const out: Record_ = {};
  for (const key of Object.keys(record).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    out[key] = record[key]!;
  }
  return out;
}

export function mergeContractManifest(base: string, ours: string, theirs: string): string | null {
  const [b, o, t] = [parse(base), parse(ours), parse(theirs)];
  if (!b || !o || !t) return null;

  const merged: Record_ = {};
  for (const key of SCALARS) {
    const value = pick(b[key], o[key], t[key]);
    if (value === "conflict") return null;
    if (value !== undefined) merged[key] = value;
  }
  if (merged.schemaVersion !== CONTRACT_MANIFEST_SCHEMA_VERSION) return null;

  const maps: Record<(typeof MAPS)[number], Record_> = { commands: {}, events: {}, domains: {} };
  for (const name of MAPS) {
    const [bm, om, tm] = [b[name] as Record_, o[name] as Record_, t[name] as Record_];
    for (const key of new Set([...Object.keys(bm), ...Object.keys(om), ...Object.keys(tm)])) {
      const value = pick(bm[key], om[key], tm[key]);
      if (value === "conflict") return null;
      if (value !== undefined) maps[name][key] = value;
    }
  }

  const commands = Object.values(maps.commands);
  const untypedByDomain: Record_ = {};
  for (const entry of commands) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) return null;
    if (entry.untyped !== true) continue;
    if (typeof entry.domain !== "string") return null;
    untypedByDomain[entry.domain] = ((untypedByDomain[entry.domain] as number) ?? 0) + 1;
  }
  const untyped = Object.values(untypedByDomain).reduce<number>((a, n) => a + (n as number), 0);

  const manifest = {
    schemaVersion: merged.schemaVersion,
    generatedBy: merged.generatedBy,
    counts: {
      commands: commands.length,
      defined: commands.length - untyped,
      untyped,
      events: Object.keys(maps.events).length,
    },
    untypedByDomain: sorted(untypedByDomain),
    domains: sorted(maps.domains),
    commands: sorted(maps.commands),
    events: sorted(maps.events),
  };
  return serializeContractManifest(manifest);
}
